 return `<svg class="discovery-art" viewBox="0 0 360 270" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><radialGradient id="card-halo"><stop stop-color="#fff4ca"/><stop offset="1" stop-color="#d9e4bf"/></radialGradient><linearGradient id="stone" x2=".8" y2="1"><stop stop-color="#d9c9aa"/><stop offset="1" stop-color="#ad9d80"/></linearGradient><linearGradient id="shell" x2="1" y2="1"><stop stop-color="#dfa45a"/><stop offset="1" stop-color="#ad7036"/></linearGradient><linearGradient id="bark" x2="1" y2="1"><stop stop-color="#b48a5b"/><stop offset="1" stop-color="#86603e"/></linearGradient><linearGradient id="beetle" x2="1" y2="1"><stop stop-color="#9dca77"/><stop offset=".5" stop-color="#60a873"/><stop offset="1" stop-color="#387b66"/></linearGradient><linearGradient id="frog" x2="0" y2="1"><stop stop-color="#b7cc78"/><stop offset="1" stop-color="#80a35b"/></linearGradient><linearGradient id="wing" x2=".8" y2="1"><stop stop-color="#f4bf67"/><stop offset="1" stop-color="#dc8b73"/></linearGradient></defs><ellipse cx="180" cy="141" rx="151" ry="122" fill="url(#card-halo)"/><g fill="#fff4c4"><path d="m52 75 3-10 3 10 10 3-10 3-3 10-3-10-10-3Z"/><path d="m295 60 2-7 2 7 7 2-7 2-2 7-2-7-7-2Z"/></g>${blades}${subject}</svg>`;
